mapper.select:
SELECT el.id, el.task_id, t.name AS task_name, el.status, el.start_time, el.end_time, el.total_records, el.success_count, el.fail_count, el.error_msg, el.cost_ms, el.page_count, el.current_stage, el.processed_count, el.updated_at, el.create_time FROM APIGRAB_EXECUTION_LOG el LEFT JOIN APIGRAB_COLLECT_TASK t ON el.task_id = t.id
AND el.task_id = #{taskId} AND t.name LIKE CONCAT('%', #{taskName}, '%') AND el.status = #{status}
ORDER BY el.id DESC

mapper.update:
UPDATE APIGRAB_EXECUTION_LOG
status = #{status}, end_time = #{endTime}, total_records = #{totalRecords}, success_count = #{successCount}, fail_count = #{failCount}, error_msg = #{errorMsg}, cost_ms = #{costMs}, page_count = #{pageCount}, current_stage = #{currentStage}, processed_count = #{processedCount}, updated_at = #{updatedAt},
WHERE id = #{id}
